bounded_host_request.command:
set -euo pipefail
db="$(docker ps --filter label=com.docker.compose.project=deploy --filter label=com.docker.compose.service=postgres --format '{{.Names}}' | head -1)"
test -n "$db"
{ echo PR47_3BOARD_PROFILE_READBACK
docker exec "$db" psql -U gace -d gaybbs -Atc "SELECT board_key || ':' || chat_id || ':' || message_thread_id || ':' || topic_id FROM posting_topics WHERE purpose='profile' AND enabled=true AND verified_at IS NOT NULL AND verified_by IS NOT NULL ORDER BY board_key;"
echo PROFILE_ROUTE_COUNT=$(docker exec "$db" psql -U gace -d gaybbs -Atc "SELECT COUNT(*) FROM posting_topics WHERE purpose='profile' AND enabled AND verified_at IS NOT NULL AND verified_by IS NOT NULL AND ((board_key='area_bbs' AND chat_id=-1003847210571 AND message_thread_id=48) OR (board_key='video_chat' AND chat_id=-1002373696859 AND message_thread_id=1613) OR (board_key='gay_board' AND chat_id=-1003770334893 AND message_thread_id=210));")
echo PROFILE_PUBLICATIONS=$(docker exec "$db" psql -U gace -d gaybbs -Atc "SELECT COUNT(*) FROM profile_publications;" 2>/dev/null || echo unavailable)
echo BOT_ACTIVE=$(docker inspect --format '{{.State.Running}}' deploy-gaybbs-1)
echo BOT_IMAGE=$(docker inspect --format '{{.Image}}' deploy-gaybbs-1)
} | gh issue comment 4 --repo seigo-gace/GateApp-Bot --body-file - >/dev/null
